1	<?php
2	
3	namespace App\Filament\Widgets\Concerns;
4	
5	use App\Enums\SportType;
6	use App\Models\User;
7	use Carbon\Carbon;
8	use Filament\Widgets\Concerns\InteractsWithPageFilters;
9	use Illuminate\Contracts\Support\Htmlable;
10	use Illuminate\Database\Eloquent\Builder;
11	use Illuminate\Support\HtmlString;
12	use Illuminate\Support\Str;
13	
14	/**
15	 * Query base condivisa dai widget di classifica: utenti con almeno
16	 * un'attività nel mese/sport selezionato, con l'aggregato passato come
17	 * $selectExpression esposto come colonna $alias per l'ordinamento.
18	 */
19	trait BuildsLeaderboardQuery
20	{
21	    use InteractsWithPageFilters;
22	
23	    public function updatedFilters(): void
24	    {
25	        $this->resetPage();
26	    }
27	
28	    protected function getLeaderboardQuery(string $selectExpression, string $alias): Builder
29	    {
30	        $month = $this->filters['month'] ?? null;
31	
32	        // ogni valore selezionato espande al proprio gruppo (es. "Run" include
33	        // anche TrailRun/VirtualRun), vedi SportType::groupMembers()
34	        $sportTypes = collect($this->filters['sportTypes'] ?? [])
35	            ->flatMap(fn (string $value) => SportType::tryFrom($value)?->groupMembers() ?? [$value])
36	            ->unique()
37	            ->values()
38	            ->all();
39	
40	        $monthStart = $month ? Carbon::createFromFormat('Y-m', $month) : Carbon::now();
41	
42	        return User::query()
43	            ->select('users.*')
44	            ->selectRaw("{$selectExpression} as {$alias}")
45	            ->join('activities', 'activities.user_id', '=', 'users.id')
46	            ->whereNull('activities.deleted_at')
47	            ->whereBetween('activities.start_date_local', [
48	                $monthStart->copy()->startOfMonth(),
49	                $monthStart->copy()->endOfMonth(),
50	            ])
51	            ->when(
52	                filled($sportTypes),
53	                fn (Builder $query) => $query->whereIn('activities.sport_type', $sportTypes)
54	            )
55	            ->groupBy('users.id')
56	            ->orderByDesc($alias);
57	    }
58	
59	    /**
60	     * Titolo del widget con immagine accanto al testo (asset in public/images/leaderboard/,
61	     * oggi placeholder in attesa delle immagini definitive). Il testo include
62	     * il nome della tab attiva (es. "Dislivello - Corsa").
63	     */
64	    protected function headingWithImage(string $imagePath, string $label): Htmlable
65	    {
66	        return new HtmlString(sprintf(
67	            '<div class="flex items-center gap-3"><img src="%s" alt="" class="h-64 w-64  rounded object-contain"><span>%s</span></div>',
68	            e(asset($imagePath)),
69	            e($this->appendActiveGroupLabel($label)),
70	        ));
71	    }
72	
73	    /**
74	     * Nome completo da firstname + lastname ("DANIELE", "basso"), normalizzato in title case.
75	     */
76	    protected function formatName(?string $firstname, ?string $lastname): string
77	    {
78	        return Str::title(trim("{$firstname} {$lastname}"));
79	    }
80	
81	    private function appendActiveGroupLabel(string $label): string
82	    {
83	        $sportType = SportType::tryFrom(($this->filters['sportTypes'] ?? [])[0] ?? '');
84	
85	        return $sportType ? "{$label} - {$sportType->getLabel()}" : $label;
86	    }
87	}
