3	namespace App\Filament\Widgets;
4	
5	use App\Enums\SpeedUnit;
6	use App\Enums\SportType;
7	use App\Filament\Widgets\Concerns\BuildsLeaderboardQuery;
8	use Filament\Tables;
9	use Filament\Tables\Table;
10	use Filament\Widgets\TableWidget as BaseWidget;
11	use Illuminate\Contracts\Support\Htmlable;
12	
13	/**
14	 * Classifica mensile per velocità media, calcolata come media pesata
15	 * (distanza totale / tempo in movimento totale) e non come media semplice
16	 * delle velocità delle singole attività: altrimenti un'unica uscita breve
17	 * e veloce falserebbe la classifica rispetto a chi percorre distanze maggiori.
18	 */
19	class SpeedLeaderboardWidget extends BaseWidget
20	{
21	    use BuildsLeaderboardQuery;
22	
23	    protected int|string|array $columnSpan = 'full';
24	
25	    protected static ?int $sort = 2;
26	
27	    protected function getTableHeading(): string|Htmlable|null
28	    {
29	        return $this->headingWithImage('images/leaderboard/speedy.svg', 'Premio Speedy Gonzales');
30	    }
31	
32	    public function table(Table $table): Table
33	    {
34	        return $table
35	            ->query($this->getLeaderboardQuery(
36	                'coalesce(sum(activities.distance), 0) / nullif(sum(activities.moving_time), 0)',
37	                'avg_speed',
38	            ))
39	            ->paginated([10, 25, 50])
40	            ->defaultPaginationPageOption(10)
41	            ->columns([
42	                Tables\Columns\TextColumn::make('rank')
43	                    ->label('#')
44	                    ->rowIndex(),
45	
46	                Tables\Columns\ImageColumn::make('profile_medium')
47	                    ->label('')
48	                    ->circular(),
49	
50	                Tables\Columns\TextColumn::make('name')
51	                    ->label('Atleta')
52	                    ->getStateUsing(fn ($record): string => $this->formatName($record->firstname, $record->lastname)),
53	
54	                Tables\Columns\TextColumn::make('avg_speed')
55	                    ->label('Vel. media')
56	                    ->formatStateUsing(fn (?float $state): string => $this->resolveSpeedUnit()->format($state))
57	                    ->alignEnd(),
58	            ]);
59	    }
60	
61	    /**
62	     * Unità dipendente dal gruppo sport della tab attiva (passo per la
63	     * corsa, km/h per la bici).
64	     */
65	    private function resolveSpeedUnit(): SpeedUnit
66	    {
67	        $sportType = SportType::tryFrom(($this->filters['sportTypes'] ?? [])[0] ?? '');
68	
69	        return $sportType?->getSpeedUnit() ?? SpeedUnit::MinutesPerKilometer;
70	    }
71	}
