    $monthStart = $month ? Carbon::createFromFormat('Y-m', $month) : Carbon::now();

    // Aggregato calcolato in una subquery raggruppata solo per user_id ed
    // eseguita in join: selezionare `users.*` insieme a un `groupBy('users.id')`
    // diretto va in errore sotto sql_mode=ONLY_FULL_GROUP_BY in produzione,
    // perché MySQL non riconosce sempre users.id come chiave funzionale in
    // presenza della join con activities.
    $activityAggregates = Activity::query()
        ->select('user_id')
        ->selectRaw("{$selectExpression} as {$alias}")
        ->whereBetween('start_date_local', [
            $monthStart->copy()->startOfMonth(),
            $monthStart->copy()->endOfMonth(),
        ])
        ->when(
            filled($sportTypes),
            fn (Builder $query) => $query->whereIn('sport_type', $sportTypes)
        )
        ->groupBy('user_id');

    return User::query()
        ->select('users.*')
        ->addSelect("agg.{$alias}")
        ->joinSub($activityAggregates, 'agg', 'agg.user_id', '=', 'users.id')
        ->orderByDesc($alias);
}

